files.examples/01_junction.sql:
-- LEARN(sql.joins.many-to-many): the junction table is the relationship.
CREATE TABLE requirements (id int PRIMARY KEY, code text NOT NULL UNIQUE);
CREATE TABLE test_cases   (id int PRIMARY KEY, title text NOT NULL);

-- One row per link. The composite key forbids duplicate links, and deleting
-- either end deletes its links.
CREATE TABLE trace_links (
  requirement_id int REFERENCES requirements ON DELETE CASCADE,
  test_case_id   int REFERENCES test_cases   ON DELETE CASCADE,
  PRIMARY KEY (requirement_id, test_case_id)
);
-- The key's index serves requirement -> tests; test -> requirements needs this.
CREATE INDEX ON trace_links (test_case_id);

INSERT INTO requirements VALUES (1, 'REQ-LOGIN'), (2, 'REQ-RESET'), (3, 'REQ-EXPORT');
INSERT INTO test_cases VALUES
  (10, 'Valid password'), (11, 'Locked account'), (12, 'Reset e-mail sent');
INSERT INTO trace_links VALUES (1, 10), (1, 11), (2, 11), (2, 12);

-- Linking the same pair again is a no-op, not a second row.
INSERT INTO trace_links VALUES (1, 10) ON CONFLICT DO NOTHING;

-- Two joins walk the relationship: requirement -> link -> test case.
SELECT r.code, t.title
FROM requirements r
JOIN trace_links l ON l.requirement_id = r.id
JOIN test_cases t  ON t.id = l.test_case_id
ORDER BY r.code, t.title;

-- Test 11 covers two requirements; deleting it removes both of its links.
DELETE FROM test_cases WHERE id = 11;
SELECT requirement_id, test_case_id FROM trace_links ORDER BY 1, 2;

files.examples/02_semi_join.sql:
CREATE TABLE requirements (id int PRIMARY KEY, code text NOT NULL UNIQUE);
CREATE TABLE test_cases   (id int PRIMARY KEY, last_passed boolean);  -- NULL: never run
CREATE TABLE trace_links (
  requirement_id int REFERENCES requirements,
  test_case_id   int REFERENCES test_cases,
  PRIMARY KEY (requirement_id, test_case_id)
);
INSERT INTO requirements VALUES (1, 'REQ-LOGIN'), (2, 'REQ-RESET'), (3, 'REQ-EXPORT');
INSERT INTO test_cases VALUES (10, true), (11, true), (12, NULL);
INSERT INTO trace_links VALUES (1, 10), (1, 11), (2, 11), (2, 12);

-- Which requirements have at least one test?
-- A join answers "list the pairs", so each requirement repeats per link.
SELECT r.code
FROM requirements r
JOIN trace_links l ON l.requirement_id = r.id
ORDER BY r.code;

-- EXISTS is a semi-join: each row of r at most once, first match is enough.
SELECT r.code
FROM requirements r
WHERE EXISTS (SELECT 1 FROM trace_links l WHERE l.requirement_id = r.id)
ORDER BY r.code;

-- Verified: at least one linked test, and no linked test that hasn't passed.
SELECT r.code
FROM requirements r
WHERE EXISTS (SELECT 1 FROM trace_links l WHERE l.requirement_id = r.id)
  AND NOT EXISTS (
    SELECT 1
    FROM trace_links l
    JOIN test_cases t ON t.id = l.test_case_id
    WHERE l.requirement_id = r.id AND t.last_passed IS NOT TRUE
  )
ORDER BY r.code;

files.examples/03_not_in_trap.sql:
CREATE TABLE test_cases (id int PRIMARY KEY, title text NOT NULL);
-- Ad-hoc runs belong to no test case: test_case_id is NULL for them.
CREATE TABLE test_runs (
  id           int PRIMARY KEY,
  test_case_id int REFERENCES test_cases,
  passed       boolean NOT NULL
);
INSERT INTO test_cases VALUES
  (10, 'Valid password'), (11, 'Locked account'), (12, 'Reset e-mail sent');
INSERT INTO test_runs VALUES (1, 10, true), (2, 10, false), (3, 12, true);

-- Which test cases never ran? Correct, as long as no NULL is around.
SELECT title FROM test_cases
WHERE id NOT IN (SELECT test_case_id FROM test_runs)
ORDER BY id;

INSERT INTO test_runs VALUES (4, NULL, true);  -- someone ran an ad-hoc check

-- The same query now returns nothing.
SELECT title FROM test_cases
WHERE id NOT IN (SELECT test_case_id FROM test_runs)
ORDER BY id;

-- Why: x NOT IN (...) is x <> each value, ANDed. One NULL makes it unknown.
SELECT 11 NOT IN (10, 12) AS without_null, 11 NOT IN (10, 12, NULL) AS with_null;

-- NOT EXISTS asks "is there a matching row?", and a NULL never matches.
SELECT t.title FROM test_cases t
WHERE NOT EXISTS (SELECT 1 FROM test_runs r WHERE r.test_case_id = t.id)
ORDER BY t.id;

-- The same anti-join as LEFT JOIN ... IS NULL.
SELECT t.title FROM test_cases t
LEFT JOIN test_runs r ON r.test_case_id = t.id
WHERE r.id IS NULL
ORDER BY t.id;
